Problem Description:
Find the bug and fix this 8-bit wide 2-to-1 mux.

// module top_module (
//     input sel,
//     input [7:0] a,
//     input [7:0] b,
//     output out  );

//     assign out = (~sel & a) | (sel & b);

// endmodule

module top_module (
	input sel,
	input [7:0] a,
	input [7:0] b,
	output reg [7:0] out
);

Erroneous Implementation:

always @(posedge clk)
begin
	if (sel == 0)
	begin
		out <= b;
	end
	else
	begin
		out <= a;
	end
end

endmodule

